def get_claim(claim_id, tenant):
    key = f"claim:{tenant}:{claim_id}"        # tenant in the key, always
    hit = redis.get(key)
    if hit is not None:
        return decode(hit)

    # Stampede guard: on a cold key, 500 concurrent misses would all hit
    # the database. One wins the lock, the rest wait for the fill.
    with redis.lock(f"lock:{key}", timeout=5, blocking_timeout=2):
        hit = redis.get(key)                  # double-check after the lock
        if hit is not None:
            return decode(hit)
        row = db.query(claim_id, tenant)
        redis.setex(key, ttl_with_jitter(300), encode(row))
        return row

-- BROKEN: read-modify-write across two statements.
SELECT credits FROM balances WHERE tenant_id = 42;   -- both read 100
UPDATE balances SET credits = 99 WHERE tenant_id = 42; -- both write 99
-- Two concurrent deductions, one credit consumed. Lost update.

-- FIX 1: atomic conditional update. Row count tells you if you won.
UPDATE balances
   SET credits = credits - 1
 WHERE tenant_id = 42 AND credits >= 1;

-- FIX 2: pessimistic lock, when you need to compute between read/write.
BEGIN;
SELECT credits FROM balances WHERE tenant_id = 42 FOR UPDATE;
-- ... other transactions block here ...
UPDATE balances SET credits = credits - 1 WHERE tenant_id = 42;
COMMIT;

async def call(fn, *, attempts=3, base=0.2, cap=5.0):
    for i in range(attempts):
        try:
            return await asyncio.wait_for(fn(), timeout=2.0)
        except (Timeout, ServiceUnavailable):
            if i == attempts - 1:
                raise
            # Full jitter beats "exponential + small random": it spreads
            # retries across the whole window instead of clustering.
            await asyncio.sleep(random.uniform(0, min(cap, base * 2 ** i)))
